const engine = document.querySelector("#engine");

// listen to keydown and keyup
document.addEventListener("keydown", (e) => {
  if (e.key !== " ") return;
  e.preventDefault();
  engine.textContent = "Engine: ON";
  engine.classList.add("on");
});

