// listen to keydown: add the key, keep the last 4, compare with the code
document.addEventListener("keydown", (e) => {
  pressed.push(e.key);
  pressed = pressed.slice(-4);
  if (pressed.join(",") === CODE.join(",")) {
    document.querySelector("#secret").textContent = "Secret mode unlocked!";
  }
});

