const ship = document.querySelector("#ship");
const STEP = 20;
const MAX_X = 270; // the field is 300px, the ship is 30px wide
let x = 0;

// The beep sound (ready-made): if it can't play, the game quietly carries on
let audio = null;
function beep(freq = 440) {
  try {
    audio = audio || new AudioContext();
    const osc = audio.createOscillator();
    const gain = audio.createGain();
    osc.frequency.value = freq;
    gain.gain.value = 0.05;
    osc.connect(gain);
    gain.connect(audio.destination);
    osc.start();
    osc.stop(audio.currentTime + 0.1);
  } catch (err) {
    // no sound is fine
  }
}

function moveShip(dx) {
  // change x, keep it between 0 and MAX_X, place the ship
  x = x + dx;
  if (x < 0 || x > MAX_X) beep(220); // hit the wall
  x = Math.max(0, Math.min(MAX_X, x));
  ship.style.left = x + "px";
}

// listen to keydown
document.addEventListener("keydown", (e) => {
  if (e.target.tagName === "INPUT") return;
  if (e.key === "ArrowLeft") {
    e.preventDefault();
    moveShip(-STEP);
  } else if (e.key === "ArrowRight") {
    e.preventDefault();
    moveShip(STEP);
  }
});
